function today(){return new Date().toISOString().slice(0,10)}
function stamp(){return new Date().toISOString().replace(/[^0-9]/g,"").slice(0,17)}
function slug(v){return String(v||"project").toLowerCase().replace(/&/g,"and").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"").slice(0,80)||"project"}
function csv(v){return String(v||"").split(",").map(x=>x.trim()).filter(Boolean)}
function uniq(a){return [...new Set((a||[]).filter(Boolean))]}
function clone(v){return JSON.parse(JSON.stringify(v))}
function pathOf(i){return typeof i==="string"?i:(i&&i.path?i.path:"")}
function nameOf(p){return String(p||"").split("/").pop()||"image"}
function ext(p){let m=String(p||"").toLowerCase().match(/\.([a-z0-9]+)$/);return m?m[1]:""}
function folderOf(p){let a=String(p||"").split("/");return a.length>2?a.slice(2,-1).join("/")||"converted":"converted"}
function titleCase(v){return String(v||"").replace(/[-_]/g," ").replace(/\b\w/g,c=>c.toUpperCase())}
function esc(v){return String(v==null?"":v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]))}
function sleep(ms){return new Promise(resolve=>Timer.schedule(ms/1000,false,resolve))}
