function normImage(i,title=""){return typeof i==="string"?{path:i,caption:"",alt:title||"Spray GenX project photo",visible:true,role:""}:{...(i||{}),path:pathOf(i),caption:i&&i.caption||"",alt:i&&i.alt||i&&i.caption||title||"Spray GenX project photo",visible:!(i&&i.visible===false),role:i&&i.role||""}}
function normalizeBlockPreserve(original,index=0,categories=[]){
  let b=original||{}, title=b.title||"Untitled Image Block";
  let cat=b.category||(Array.isArray(b.categories)&&b.categories[0])||(categories[0]&&categories[0].id)||"uncategorized";
  let images=imageList(b).map(i=>normImage(i,title)).filter(i=>i.path);
  let locations=uniq([...(Array.isArray(b.siteLocations)?b.siteLocations:[]),...Object.keys(b.views||{}).filter(k=>b.views[k])]);
  if(!locations.length)locations=DEFAULT_VIEWS.slice();
  let weight=Number.isFinite(Number(b.weight))?Number(b.weight):(Number.isFinite(Number(b.priority))?Number(b.priority):25);
  return {...b,id:b.id||`${slug(title)}-missing-${index+1}`,slug:b.slug||slug(title),title,summary:b.summary!=null?b.summary:(b.description||""),customer:b.customer||"",location:b.location||"",date:b.date||today(),category:cat,categories:uniq([cat,...(Array.isArray(b.categories)?b.categories:[])]),tags:Array.isArray(b.tags)?b.tags:csv(b.tags),projectStatus:workflowStatus(b),status:b.status||(b.visible===false?"hidden":"published"),visible:b.visible!==false,weight,priority:Number.isFinite(Number(b.priority))?Number(b.priority):weight,views:{...(b.views||{}),...Object.fromEntries(locations.map(x=>[x,true]))},siteLocations:locations,fallback:b.fallback||"latest",cover:b.cover||(images[0]&&images[0].path)||"",images};
}
function normalizeLibraryPreserve(original){let l=original||{},categories=Array.isArray(l.categories)?l.categories:[],blocks=Array.isArray(l.blocks)?l.blocks:[];return {...l,categories:categories.map(c=>({...c})),blocks:blocks.map((b,i)=>normalizeBlockPreserve(b,i,categories))}}
