function resizeForUpload(img,maxEdge){let w=img.size.width,h=img.size.height,longest=Math.max(w,h);if(longest<=maxEdge)return img;let scale=maxEdge/longest,nw=Math.max(1,Math.round(w*scale)),nh=Math.max(1,Math.round(h*scale));let dc=new DrawContext();dc.size=new Size(nw,nh);dc.opaque=true;dc.respectScreenScale=false;dc.drawImageInRect(img,new Rect(0,0,nw,nh));return dc.getImage()}
function jpegForUpload(img){let edge=MAX_IMAGE_EDGE,work=resizeForUpload(img,edge),data=Data.fromJPEG(work);while(data.length>MAX_UPLOAD_BYTES&&edge>900){edge=Math.max(900,Math.floor(edge*.8));work=resizeForUpload(img,edge);data=Data.fromJPEG(work)}if(data.length>MAX_UPLOAD_BYTES)throw new Error("Photo is still larger than 8 MB after resizing. Crop it slightly in Photos and try again.");return data}
async function imageFromFile(path){let fm=FileManager.local();if(!RAW_ALLOWED.includes(ext(path)))throw new Error(`Unsupported file type: ${ext(path)||"unknown"}`);let data=fm.read(path),img=Image.fromData(data);if(!img)throw new Error(`Could not read ${nameOf(path)} as an image.`);return img}
async function progress(stage,done,total,project){await notify(stage,done?`${project}: ${done} of ${total}`:project)}

async function attachPathsToBlockId(blockId,paths){let uniquePaths=uniq(paths);if(!uniquePaths.length)return (await liveLibrary()).json.blocks.find(b=>b.id===blockId);return safeMutateBlock(blockId,async n=>{n.images=imageList(n).map(i=>normImage(i,n.title));let have=new Set(n.images.map(pathOf));uniquePaths.forEach(p=>{if(!have.has(p)){n.images.push({path:p,caption:"",alt:n.title||"Project image",visible:true,role:""});have.add(p)}});if(!n.cover&&n.images.length)n.cover=pathOf(n.images[0]);n.images.forEach(i=>{if(pathOf(i)===n.cover)i.role="cover";else if(i.role==="cover")i.role=""})},`Attach ${uniquePaths.length} image(s) to project ${blockId}`,saved=>uniquePaths.every(p=>imageList(saved).some(i=>pathOf(i)===p)))}
async function uploadImagesToBlock(blockId,images,sourceLabel="Photos"){
  images=(images||[]).filter(Boolean).slice(0,MAX_BATCH);if(!images.length)return null;
  return runBusy(async()=>{let live=await liveLibrary(),block=live.json.blocks.find(b=>b.id===blockId);if(!block)throw new Error("Selected project no longer exists in GitHub.");let run=stamp(),paths=[];await progress("Preparing Images",0,images.length,block.title);
    for(let i=0;i<images.length;i++){let file=`photo-${run}-${String(i+1).padStart(3,"0")}.jpg`,repoPath=`${INBOX_ROOT}/${slug(block.id)}/${file}`,data=jpegForUpload(images[i]);await progress("Uploading Images",i+1,images.length,block.title);await putBinaryVerified(repoPath,data,`Upload photo: ${block.title}`);paths.push(repoPath)}
    await progress("Updating Project",0,images.length,block.title);let saved=await attachPathsToBlockId(block.id,paths);await progress("Complete",paths.length,paths.length,saved.title);await alertMsg("Upload Complete & Verified",`${paths.length} image${paths.length===1?"":"s"} resized to JPEG and uploaded from ${sourceLabel}.\n\nAttached to ${saved.title}\nBlock ID: ${saved.id}\nGitHub read-back verified.`);return saved});
}
async function pickOnePhoto(blockId){let img;try{img=await Photos.fromLibrary()}catch(_){return null}return img?uploadImagesToBlock(blockId,[img],"Photo Library"):null}
async function pickManyPhotos(blockId){let images=[];while(images.length<MAX_BATCH){let img;try{img=await Photos.fromLibrary()}catch(_){break}if(!img)break;images.push(img);let a=await choose("Select Photos",[{label:"Add Another Photo",id:"more"},{label:`Upload ${images.length} Selected`,id:"upload"}],`${images.length} of ${MAX_BATCH} selected`);if(!a)return null;if(a.id==="upload")break}return images.length?uploadImagesToBlock(blockId,images,"Photo Library batch"):null}
async function pickFiles(blockId){let paths=[];try{paths=await DocumentPicker.open(["public.image"])}catch(e){await alertMsg("File Picker Error",String(e.message||e));return null}if(!Array.isArray(paths))paths=paths?[paths]:[];paths=uniq(paths).slice(0,MAX_BATCH);if(!paths.length)return null;let bad=paths.filter(p=>!RAW_ALLOWED.includes(ext(p)));if(bad.length){await alertMsg("Unsupported File",`Allowed: ${RAW_ALLOWED.join(", ")}\n\nNot accepted: ${uniq(bad.map(nameOf)).join(", ")}`);return null}let images=[];for(let p of paths)images.push(await imageFromFile(p));return uploadImagesToBlock(blockId,images,"Files picker")}
async function importShared(blockId){let images=Array.isArray(args.images)?args.images.filter(Boolean).slice(0,MAX_BATCH):[];if(!images.length){await alertMsg("No Shared Photos","Photos → Select → choose photos → Share → Scriptable → Spray GenX Image Manager.");return null}SHARED_IMAGES_USED=true;return uploadImagesToBlock(blockId,images,`Share Sheet (${images.length} selected)`)}

async function convertedAvailable(){let converted;try{converted=await getJson(CONVERTED_PATH)}catch(e){await alertMsg("Converted Images Unavailable","data/converted-images.json could not be loaded.");return []}let live=await liveLibrary(),used=new Set();live.json.blocks.forEach(b=>imageList(b).forEach(i=>used.add(pathOf(i))));return (Array.isArray(converted.json.images)?converted.json.images:[]).filter(x=>x.converted&&x.status!=="ignored"&&!used.has(x.converted))}
async function chooseConvertedPaths(){let avail=await convertedAvailable();if(!avail.length){await alertMsg("Nothing New","No unattached converted images were found.");return []}let groups={};avail.forEach(x=>{let f=folderOf(x.converted);(groups[f]=groups[f]||[]).push(x)});let g=await choose("Converted Images",Object.keys(groups).sort().map(k=>({label:`${titleCase(k)} · ${groups[k].length} images`,id:k})).concat([{label:`All Unassigned · ${avail.length} images`,id:"__all"}]),"Choose a converted batch.");if(!g)return [];let batch=g.id==="__all"?avail:groups[g.id];let selected=[];while(batch.length){let remaining=batch.filter(x=>!selected.includes(x.converted));let p=await choose("Select Converted Images",remaining.slice(0,45).map(x=>({label:nameOf(x.converted),path:x.converted})).concat([{label:`Attach Selected (${selected.length})`,path:"__done"},{label:`Attach Entire Batch (${batch.length})`,path:"__all"}]),"Select individual images or attach the entire batch.");if(!p)return [];if(p.path==="__done")break;if(p.path==="__all")return batch.map(x=>x.converted);selected.push(p.path);if(selected.length===batch.length)break}return selected}
async function attachConverted(blockId){let paths=await chooseConvertedPaths();if(!paths.length)return null;let saved=await runBusy(()=>attachPathsToBlockId(blockId,paths));if(saved)await alertMsg("Converted Images Attached",`${paths.length} image${paths.length===1?"":"s"} attached to ${saved.title}.\n\nBlock ID: ${saved.id}\nVerified from GitHub.`);return saved}

function editorPayloadScript(){return `function values(action){if(window.__sgxSubmitted)return;window.__sgxSubmitted=true;let extra=[...document.querySelectorAll('input[name=additional]:checked')].map(x=>x.value);let payload={action,title:v('title').trim(),summary:v('summary').trim(),customer:v('customer').trim(),location:v('location').trim(),slug:v('slug').trim(),category:v('category'),categories:extra,tags:v('tags').trim(),projectStatus:v('projectStatus'),visibility:v('visibility'),weight:v('weight').trim()};document.getElementById('busy').style.display='block';document.querySelectorAll('button').forEach(x=>x.disabled=true);window.location.href='scriptable:///sgx-project-editor?data='+encodeURIComponent(JSON.stringify(payload))}function v(id){return document.getElementById(id).value}`}
async function projectEditorPage(block,library){
  let b=normalizeBlockPreserve(block,0,library.categories),categories=library.categories.slice().sort((a,z)=>(Number(a.sort)||999)-(Number(z.sort)||999));if(!categories.some(c=>c.id===b.category))categories.push({id:b.category,label:categoryLabel(b.category,library)});
  let primary=categories.map(c=>`<option value="${esc(c.id)}" ${c.id===b.category?"selected":""}>${esc(c.label)}</option>`).join("");
  let additional=categories.filter(c=>c.id!==b.category).map(c=>`<label class="check"><input type="checkbox" name="additional" value="${esc(c.id)}" ${categoryIds(b).includes(c.id)?"checked":""}><span>${esc(c.label)}</span></label>`).join("")||'<div class="muted">No additional categories yet.</div>';
  let cards=imageList(b).map((im,i)=>{let x=normImage(im,b.title),p=pathOf(x),cover=p===b.cover||x.role==="cover";return `<button class="card" onclick="values('image:${i}')"><img src="${esc(rawUrl(p))}" loading="lazy"><span>${cover?"★ COVER · ":""}${x.visible?"":"HIDDEN · "}${i+1}</span></button>`}).join("")||'<div class="empty">No images yet. Tap Add Images.</div>';
  let state=publishStatus(b),shared=Array.isArray(args.images)&&args.images.length&&!SHARED_IMAGES_USED;
  let html=`<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1"><style>
  *{box-sizing:border-box}body{margin:0;background:#081522;color:#f5f8fb;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;padding:14px 14px 112px}header{padding:5px 2px 12px}h1{font-size:24px;margin:0 0 7px}.meta{font-size:12px;color:#92a9bd;word-break:break-all}.badge{display:inline-block;padding:5px 9px;border-radius:999px;background:${state==="LIVE"?"#0b7554":state==="DRAFT"?"#705b18":"#73333c"};color:#fff;font-weight:800;font-size:12px;margin-bottom:8px}.section{background:#102334;border:1px solid #253d51;border-radius:14px;padding:14px;margin:0 0 14px}.section h2{font-size:17px;margin:0 0 14px}.field{margin-bottom:14px}.field:last-child{margin-bottom:0}label.caption{display:block;font-size:13px;font-weight:750;color:#dbe8f3;margin:0 0 7px}input,textarea,select{width:100%;min-height:48px;border:1px solid #385269;border-radius:10px;background:#0a1b2a;color:#fff;padding:11px 12px;font-size:16px}textarea{min-height:102px;resize:vertical}.row{display:grid;grid-template-columns:1fr 1fr;gap:10px}.checks{display:grid;gap:8px}.check{display:flex;align-items:center;gap:10px;min-height:44px;background:#0a1b2a;border-radius:10px;padding:8px 11px}.check input{width:22px;min-height:22px;margin:0}.toolbar{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:12px}.btn{min-height:46px;border:1px solid #355069;border-radius:11px;background:#173149;color:#fff;font-size:14px;font-weight:750;padding:10px}.btn.primary{background:#087ec2;border-color:#1597e3}.btn.warn{background:#5b2830;border-color:#85434e}.grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.card{padding:0;border:1px solid #2d465b;border-radius:11px;overflow:hidden;background:#091a29;color:#fff;text-align:left;min-height:44px}.card img{display:block;width:100%;aspect-ratio:1/1;object-fit:cover;background:#172a39}.card span{display:block;padding:8px;font-size:11px;font-weight:800}.empty,.muted{color:#8fa5b8;font-size:13px}.sticky{position:fixed;z-index:5;left:0;right:0;bottom:0;padding:10px 14px calc(10px + env(safe-area-inset-bottom));background:rgba(8,21,34,.97);border-top:1px solid #294257;display:grid;grid-template-columns:1fr 1fr;gap:10px}.sticky button{min-height:50px;border:0;border-radius:12px;color:#fff;font-size:15px;font-weight:850}.draft{background:#30465a}.publish{background:#0786d1}#busy{display:none;position:fixed;z-index:8;inset:0;background:rgba(3,10,16,.86);padding-top:42vh;text-align:center;font-size:18px;font-weight:800}.back{width:100%;margin-top:4px;background:transparent;border-color:#355069}@media(max-width:390px){.row{grid-template-columns:1fr}.toolbar{grid-template-columns:1fr}.section{padding:12px}.grid{gap:7px}}</style></head><body>
  <div id="busy">Working… return to Scriptable</div><header><span class="badge">${state}</span><h1>${esc(b.title)}</h1><div class="meta">Permanent Block ID · ${esc(b.id)}</div></header>
  <section class="section"><h2>1 · Project</h2><div class="field"><label class="caption">Project Title</label><input id="title" value="${esc(b.title)}"></div><div class="field"><label class="caption">Description / Summary</label><textarea id="summary">${esc(b.summary)}</textarea></div><div class="row"><div class="field"><label class="caption">Customer</label><input id="customer" value="${esc(b.customer)}"></div><div class="field"><label class="caption">Location</label><input id="location" value="${esc(b.location)}"></div></div><div class="field"><label class="caption">URL Slug</label><input id="slug" value="${esc(b.slug)}"></div><div class="field"><label class="caption">Tags (comma separated)</label><input id="tags" value="${esc((b.tags||[]).join(", "))}"></div><div class="field"><label class="caption">Priority / Weight</label><input id="weight" inputmode="numeric" value="${esc(b.weight)}"></div></section>
  <section class="section"><h2>2 · Categories</h2><div class="field"><label class="caption">Primary Category</label><select id="category">${primary}</select></div><label class="caption">Additional Categories</label><div class="checks">${additional}</div><div class="toolbar"><button class="btn" onclick="values('createCategory')">＋ Create Category</button><button class="btn" onclick="values('manageCategories')">Manage Categories</button></div></section>
  <section class="section"><h2>3 · Images · ${imageList(b).length}</h2><div class="muted" style="margin-bottom:10px">Tap a thumbnail to preview, edit metadata, set the cover, reorder, show/hide, or remove it from this project.</div><div class="grid">${cards}</div><div class="toolbar"><button class="btn primary" onclick="values('addImages')">＋ Add Images</button><button class="btn" onclick="values('previewImages')">Preview Gallery</button>${shared?'<button class="btn" onclick="values(\'shared\')">Import Shared Photos</button>':""}</div></section>
  <section class="section"><h2>4 · Publishing</h2><div class="row"><div class="field"><label class="caption">Project Status</label><select id="projectStatus"><option value="work-in-progress" ${b.projectStatus==="work-in-progress"?"selected":""}>Work in Progress</option><option value="completed" ${b.projectStatus==="completed"?"selected":""}>Completed</option><option value="draft" ${b.projectStatus==="draft"?"selected":""}>Draft</option></select></div><div class="field"><label class="caption">Website Visibility</label><select id="visibility"><option value="visible" ${b.visible!==false?"selected":""}>Visible</option><option value="hidden" ${b.visible===false?"selected":""}>Hidden</option></select></div></div><button class="btn" style="width:100%" onclick="values('save')">Save Changes</button></section>
  <section class="section"><h2>5 · Advanced / Tools</h2><div class="toolbar"><button class="btn" onclick="values('health')">Health Check</button><button class="btn" onclick="values('reload')">Reload Project</button><button class="btn warn" onclick="values('delete')">Delete Project</button><button class="btn back" onclick="values('back')">Back to Projects</button></div></section>
  <div class="sticky"><button class="draft" onclick="values('draft')">Save Draft</button><button class="publish" onclick="values('publish')">Save & Publish</button></div><script>window.__sgxSubmitted=false;${editorPayloadScript()}</script></body></html>`;
  let w=new WebView();w.shouldAllowRequest=req=>{let u=String(req&&req.url||"");if(u.startsWith("scriptable:///sgx-project-editor?data=")){try{w.__result=JSON.parse(decodeURIComponent(u.split("?data=")[1]))}catch(_){w.__result={action:"back"}}try{w.dismiss()}catch(_){}return false}return true};await w.loadHTML(html);await w.present(true);return w.__result||{action:"back"};
}
function patchFromEditor(n,r,mode){n.title=r.title||n.title;n.summary=r.summary;n.customer=r.customer;n.location=r.location;n.slug=slug(r.slug||n.title);n.category=r.category||"uncategorized";n.categories=uniq([n.category,...(r.categories||[]).filter(x=>x!==n.category)]);n.tags=csv(r.tags);n.projectStatus=r.projectStatus||"work-in-progress";let weight=Math.max(0,Math.min(100,Number(r.weight)||25));n.weight=weight;n.priority=weight;if(mode==="draft"){n.status="draft";n.visible=false}else if(mode==="publish"){n.status="published";n.visible=r.visibility!=="hidden";n.date=today()}}
function verifyEditor(r,mode){return (saved,before)=>{let fields=saved.title===(r.title||saved.title)&&saved.summary===r.summary&&saved.customer===r.customer&&saved.location===r.location&&saved.slug===slug(r.slug||r.title)&&saved.category===r.category&&sameJson(categoryIds(saved),uniq([r.category,...(r.categories||[]).filter(x=>x!==r.category)]))&&sameJson(saved.tags||[],csv(r.tags))&&workflowStatus(saved)===(r.projectStatus||"work-in-progress");if(!fields)return false;if(mode==="keep")return saved.status===before.status&&saved.visible===before.visible;if(mode==="draft")return saved.status==="draft"&&saved.visible===false;return saved.status==="published"&&saved.visible===(r.visibility!=="hidden")}}
async function saveEditor(blockId,r,mode,quiet=false){let saved=await runBusy(()=>safeMutateBlock(blockId,async n=>patchFromEditor(n,r,mode),`${mode==="draft"?"Save draft":mode==="publish"?"Publish":"Save changes to"} project: ${blockId}`,verifyEditor(r,mode)));if(saved&&!quiet)await alertMsg(mode==="draft"?"Draft Saved & Verified":"Published & Verified",`${saved.title}\nBlock ID: ${saved.id}\nWebsite: ${saved.visible===false?"Hidden":"Visible"}\nGitHub read-back verified.`);return saved}
async function persistBeforeAction(blockId,r){return saveEditor(blockId,r,"keep",true)}

async function newProject(){let title=await ask("New Project","Project title","");if(!title)return null;let id=`${slug(title)}-${stamp()}`,live=await liveLibrary(),cat=live.json.categories[0]&&live.json.categories[0].id||"uncategorized";let b={id,slug:slug(title),title,summary:"",customer:"",location:"",date:today(),category:cat,categories:[cat],tags:[],projectStatus:"work-in-progress",status:"draft",visible:false,weight:25,priority:25,views:{library:true,latest:true,search:true},siteLocations:DEFAULT_VIEWS.slice(),fallback:"latest",cover:"",images:[]};let saved=await runBusy(()=>safeCreateBlock(b,`Create project: ${title}`));if(saved)await alertMsg("Project Created & Verified",`${saved.title}\n\nPermanent Block ID:\n${saved.id}\n\nThe new project will open now.`);return saved}

async function createCategoryForProject(blockId){let label=await ask("Create Category","Category name","");if(!label)return null;let id=slug(label),live=await liveLibrary(),exists=live.json.categories.find(c=>c.id===id);if(!exists){await runBusy(()=>safeMutateLibrary(async l=>{if(!l.categories.some(c=>c.id===id))l.categories.push({id,label,sort:Math.max(0,...l.categories.map(c=>Number(c.sort)||0))+10})},`Create category: ${label}`,l=>l.categories.some(c=>c.id===id&&c.label===label)))}let how=await choose(exists?"Category Already Exists":"Category Created",[{label:"Set as Primary Category",id:"primary"},{label:"Add as Additional Category",id:"additional"},{label:"Create Only",id:"only"}],exists?`${exists.label} already exists. No duplicate was created.`:`${label} is now available throughout the Image Manager.`);if(!how||how.id==="only")return null;return runBusy(()=>safeMutateBlock(blockId,async n=>{if(how.id==="primary")n.category=id;n.categories=uniq([n.category||id,...categoryIds(n),id])},`Assign category ${id} to ${blockId}`,s=>how.id==="primary"?s.category===id:categoryIds(s).includes(id)))}
function categoryUsage(l,id){let primary=[],additional=[];(l.blocks||[]).forEach(b=>{if(b.category===id)primary.push(b);else if(categoryIds(b).includes(id))additional.push(b)});return{primary,additional,total:primary.length+additional.length}}
async function renameCategory(category){let label=await ask("Rename Category","Category label",category.label);if(!label||label===category.label)return;await runBusy(()=>safeMutateLibrary(async l=>{let c=l.categories.find(x=>x.id===category.id);if(!c)throw new Error("Category no longer exists.");c.label=label},`Rename category: ${category.id}`,l=>{let c=l.categories.find(x=>x.id===category.id);return c&&c.label===label}));await alertMsg("Category Renamed",`The stable category ID remains ${category.id}. Project references were preserved.`)}
async function deleteCategory(category){let live=await liveLibrary(),usage=categoryUsage(live.json,category.id),replacement="uncategorized";if(category.id==="uncategorized"){await alertMsg("Cannot Delete","Uncategorized is the safety replacement category.");return}if(usage.primary.length){let choices=live.json.categories.filter(c=>c.id!==category.id).map(c=>({label:c.label,id:c.id}));let p=await choose("Replacement Category",choices,`${category.label} is the Primary Category for ${usage.primary.length} project${usage.primary.length===1?"":"s"}. Choose a replacement.`);if(!p)return;replacement=p.id}let ok=await confirm("Delete Category?",`${category.label} is used by ${usage.total} project${usage.total===1?"":"s"}.\n\nPrimary references will move to ${categoryLabel(replacement,live.json)}. Additional references will be removed. No projects or image files will be deleted.`,"Delete Category");if(!ok)return;await runBusy(()=>safeMutateLibrary(async l=>{l.categories=l.categories.filter(c=>c.id!==category.id);l.blocks.forEach(b=>{if(b.category===category.id)b.category=replacement;if(Array.isArray(b.categories))b.categories=uniq([b.category,...b.categories.filter(id=>id!==category.id)])})},`Delete category: ${category.id}`,l=>!l.categories.some(c=>c.id===category.id)&&l.blocks.every(b=>b.category!==category.id&&!categoryIds(b).includes(category.id))));await alertMsg("Category Deleted & Verified",`${category.label} was removed safely. Project count did not change.`)}
async function manageCategories(){while(true){let live=await liveLibrary(),p=await choose("Manage Categories",live.json.categories.slice().sort((a,z)=>(Number(a.sort)||999)-(Number(z.sort)||999)).map(c=>{let u=categoryUsage(live.json,c.id);return{label:`${c.label} · ${u.total} projects`,category:c}}).concat([{label:"Done",done:true}]),"Rename, inspect usage, or delete a category.");if(!p||p.done)return;let u=categoryUsage(live.json,p.category.id),action=await choose(p.category.label,[{label:"Rename Category",id:"rename"},{label:"Delete Category",id:"delete",destructive:true}],`Used by ${u.total} projects (${u.primary.length} primary, ${u.additional.length} additional).\nStable ID: ${p.category.id}`);if(!action)continue;if(action.id==="rename")await renameCategory(p.category);if(action.id==="delete")await deleteCategory(p.category)}}

async function previewImage(image){try{let r=new Request(rawUrl(pathOf(image)));r.headers={Authorization:`Bearer ${GITHUB_TOKEN}`};r.timeoutInterval=45;await QuickLook.present(await r.loadImage(),true)}catch(e){await alertMsg("Preview Failed",String(e.message||e))}}
async function previewGallery(block){let cards=imageList(block).filter(i=>pathOf(i)).map((im,i)=>{let x=normImage(im,block.title),cover=pathOf(x)===block.cover||x.role==="cover";return `<figure><a href="${esc(rawUrl(pathOf(x)))}"><img src="${esc(rawUrl(pathOf(x)))}"></a><figcaption>${i+1}${cover?" · COVER":""}${x.visible?"":" · HIDDEN"}<br>${esc(x.caption||nameOf(pathOf(x)))}</figcaption></figure>`}).join("");if(!cards){await alertMsg("No Images","Add an image first.");return}let w=new WebView();await w.loadHTML(`<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{background:#081522;color:#fff;font-family:-apple-system;padding:14px}h1{font-size:22px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}figure{margin:0;background:#102334;border-radius:11px;overflow:hidden}img{display:block;width:100%;aspect-ratio:1;object-fit:cover}figcaption{padding:8px;font-size:11px}</style><h1>${esc(block.title)}</h1><div class="grid">${cards}</div>`);await w.present(true)}
async function imageAction(block,index){let current=normImage(imageList(block)[index],block.title);if(!current.path)return block;let p=await choose(nameOf(current.path),[{label:"Preview",id:"preview"},{label:"Edit Caption / Alt Text",id:"meta"},{label:current.path===block.cover?"★ Current Cover":"Set as Cover",id:"cover"},{label:current.visible?"Hide Image":"Show Image",id:"visibility"},{label:"Move Earlier",id:"earlier"},{label:"Move Later",id:"later"},{label:"Remove from Project",id:"remove",destructive:true}],`${index+1} of ${imageList(block).length}\nThe physical GitHub file is not deleted by Remove from Project.`);if(!p)return block;if(p.id==="preview"){await previewImage(current);return block}if(p.id==="meta"){let v=await askFields("Image Details",nameOf(current.path),[{label:"Caption",value:current.caption},{label:"Alt text",value:current.alt}]);if(!v)return block;return runBusy(()=>safeMutateBlock(block.id,async n=>{n.images=imageList(n).map(i=>normImage(i,n.title));let x=n.images.find(i=>pathOf(i)===current.path);if(!x)throw new Error("Image changed before save.");x.caption=v[0];x.alt=v[1]||n.title},`Edit image metadata: ${block.id}`,s=>{let x=imageList(s).find(i=>pathOf(i)===current.path);return x&&normImage(x).caption===v[0]&&normImage(x).alt===(v[1]||s.title)}))}if(p.id==="cover")return runBusy(()=>safeMutateBlock(block.id,async n=>{n.cover=current.path;n.images=imageList(n).map(i=>{let x=normImage(i,n.title);x.role=pathOf(x)===current.path?"cover":"";return x})},`Set cover image: ${block.id}`,s=>s.cover===current.path&&imageList(s).filter(i=>normImage(i).role==="cover").length===1));if(p.id==="visibility")return runBusy(()=>safeMutateBlock(block.id,async n=>{n.images=imageList(n).map(i=>normImage(i,n.title));let x=n.images.find(i=>pathOf(i)===current.path);if(!x)throw new Error("Image changed before save.");x.visible=!current.visible},`Change image visibility: ${block.id}`,s=>{let x=imageList(s).find(i=>pathOf(i)===current.path);return x&&normImage(x).visible===!current.visible}));if(p.id==="earlier"||p.id==="later"){let old=imageList(block).findIndex(x=>pathOf(x)===current.path),target=Math.max(0,Math.min(imageList(block).length-1,old+(p.id==="earlier"?-1:1)));return runBusy(()=>safeMutateBlock(block.id,async n=>{n.images=imageList(n).map(i=>normImage(i,n.title));let i=n.images.findIndex(x=>pathOf(x)===current.path),j=Math.max(0,Math.min(n.images.length-1,i+(p.id==="earlier"?-1:1)));if(i!==j)[n.images[i],n.images[j]]=[n.images[j],n.images[i]]},`Reorder image: ${block.id}`,s=>pathOf(imageList(s)[target])===current.path))}if(p.id==="remove"){if(!await confirm("Remove from Project?",`${nameOf(current.path)} will be detached from ${block.title}.\n\nThe physical GitHub image file will remain.`,"Remove from Project"))return block;return runBusy(()=>safeMutateBlock(block.id,async n=>{n.images=imageList(n).filter(i=>pathOf(i)!==current.path).map(i=>normImage(i,n.title));if(n.cover===current.path)n.cover=pathOf(n.images[0])||"";n.images.forEach(i=>{i.role=pathOf(i)===n.cover?"cover":(i.role==="cover"?"":i.role)})},`Detach image: ${block.id}`,s=>!imageList(s).some(i=>pathOf(i)===current.path)))}return block}
async function addImagesMenu(blockId){let items=[{label:"Choose One Photo",id:"one"},{label:`Choose Multiple Photos (up to ${MAX_BATCH})`,id:"many"},{label:`Select Multiple Files (up to ${MAX_BATCH})`,id:"files"},{label:"Attach Converted Images",id:"converted"},{label:"Share Sheet Instructions",id:"sharehelp"}];if(Array.isArray(args.images)&&args.images.length&&!SHARED_IMAGES_USED)items.unshift({label:`Import ${Math.min(args.images.length,MAX_BATCH)} Shared Photos`,id:"shared"});let p=await choose("Add Images",items,"Destination is already locked to this project's permanent Block ID.");if(!p)return null;if(p.id==="one")return pickOnePhoto(blockId);if(p.id==="many")return pickManyPhotos(blockId);if(p.id==="files")return pickFiles(blockId);if(p.id==="converted")return attachConverted(blockId);if(p.id==="shared")return importShared(blockId);await alertMsg("Share Sheet Import","In Photos: Select → choose multiple photos → Share → Scriptable → Spray GenX Image Manager.\n\nThe manager will ask you to select the destination project before uploading.");return null}

function healthIssues(library,onlyId=null){let issues=[],ids=new Map(),valid=new Set((library.categories||[]).map(c=>c.id));(library.blocks||[]).forEach((raw,index)=>{if(onlyId&&raw.id!==onlyId)return;let b=normalizeBlockPreserve(raw,index,library.categories),prefix=b.title||`Project ${index+1}`;if(!raw.id)issues.push(`${prefix}: missing Block ID`);else ids.set(raw.id,(ids.get(raw.id)||0)+1);if(!raw.title)issues.push(`${prefix}: missing title`);if(!raw.summary&&!raw.description)issues.push(`${prefix}: missing summary`);if(!raw.category)issues.push(`${prefix}: missing primary category`);else if(!valid.has(raw.category))issues.push(`${prefix}: invalid category ${raw.category}`);categoryIds(raw).filter(id=>!valid.has(id)).forEach(id=>issues.push(`${prefix}: unknown category ${id}`));let paths=imageList(raw).map(pathOf).filter(Boolean),dups=paths.filter((p,i)=>paths.indexOf(p)!==i);if(!paths.length)issues.push(`${prefix}: missing images`);if(!raw.cover)issues.push(`${prefix}: missing cover`);else if(!paths.includes(raw.cover))issues.push(`${prefix}: cover not present in image list`);uniq(dups).forEach(p=>issues.push(`${prefix}: duplicate image ${nameOf(p)}`))});if(!onlyId)for(let [id,count] of ids)if(count>1)issues.push(`Duplicate Block ID: ${id} (${count})`);return issues}
async function healthCheck(blockId=null){let live=await liveLibrary(),issues=healthIssues(live.json,blockId);await alertMsg(issues.length?"Health Check — Attention":"Health Check — Clear",issues.length?`${issues.length} issue${issues.length===1?"":"s"} found. No automatic repairs were made.\n\n${issues.slice(0,45).join("\n")}${issues.length>45?`\n\n…and ${issues.length-45} more.`:""}`:"No requested health issues were detected.")}
async function counts(){let live=await liveLibrary(),b=live.json.blocks,attention=new Set();healthIssues(live.json).forEach(issue=>{let found=b.find(x=>issue.startsWith((x.title||"")+":"));if(found)attention.add(found.id)});await alertMsg("Counts",`Projects: ${b.length}\nPublished: ${b.filter(x=>x.status==="published").length}\nDraft: ${b.filter(x=>x.status==="draft").length}\nHidden: ${b.filter(x=>x.visible===false).length}\nImages: ${b.reduce((n,x)=>n+imageList(x).length,0)}\nCategories: ${live.json.categories.length}\nProjects needing attention: ${attention.size}`)}
async function exportJson(){let live=await liveLibrary(),normalized=normalizeLibraryPreserve(live.json);Pasteboard.copyString(JSON.stringify(normalized,null,2)+"\n");await alertMsg("Live JSON Copied",`The current GitHub image-library.json was refreshed, normalized without dropping unknown fields, and copied to the clipboard.\n\nProjects: ${normalized.blocks.length}`)}
async function reloadLibrary(){await liveLibrary();await alertMsg("Library Reloaded","Fresh image-library.json loaded from GitHub. No project data was changed.")}

async function selectProject(message="Open a project. Its permanent Block ID remains active until you leave."){let search="";while(true){let live=await liveLibrary(),blocks=live.json.blocks.slice();if(SORT==="az")blocks.sort((a,b)=>(a.title||"").localeCompare(b.title||""));if(SORT==="za")blocks.sort((a,b)=>(b.title||"").localeCompare(a.title||""));if(SORT==="new")blocks.sort((a,b)=>(b.date||"").localeCompare(a.date||""));if(SORT==="old")blocks.sort((a,b)=>(a.date||"").localeCompare(b.date||""));if(search)blocks=blocks.filter(b=>`${b.title||""} ${b.customer||""} ${b.location||""}`.toLowerCase().includes(search.toLowerCase()));let items=blocks.map(b=>({label:`${b.title||"Untitled"}\n${publishStatus(b)} · ${categoryLabel(b.category,live.json)} · ${imageList(b).length} images`,id:b.id}));items.push({label:"⌕ Search Projects",id:"__search"},{label:`⇅ Sort · ${{az:"A–Z",za:"Z–A",new:"Newest",old:"Oldest"}[SORT]}`,id:"__sort"},{label:"＋ New Project",id:"__new"});let p=await choose("Projects",items,search?`Search: ${search}`:message);if(!p)return null;if(p.id==="__search"){let q=await ask("Search Projects","Title, customer, or location",search);if(q!==null)search=q;continue}if(p.id==="__sort"){let s=await choose("Sort Projects",[{label:"A–Z",id:"az"},{label:"Z–A",id:"za"},{label:"Newest",id:"new"},{label:"Oldest",id:"old"}]);if(s)SORT=s.id;continue}if(p.id==="__new")return newProject();return live.json.blocks.find(b=>b.id===p.id)}}

async function openProject(initial){let blockId=initial.id;while(true){let live=await liveLibrary(),block=live.json.blocks.find(b=>b.id===blockId);if(!block){await alertMsg("Project Unavailable","This project no longer exists in the live GitHub library.");return}let r=await projectEditorPage(block,live.json);if(!r||r.action==="back")return;if(r.action==="draft"){await saveEditor(blockId,r,"draft");continue}if(r.action==="publish"){await saveEditor(blockId,r,"publish");continue}if(r.action==="save"){let saved=await saveEditor(blockId,r,"keep",true);await alertMsg("Changes Saved & Verified",`${saved.title}\nBlock ID: ${saved.id}\nPublishing state was preserved.`);continue}if(r.action==="reload")continue;if(r.action==="health"){await healthCheck(blockId);continue}if(r.action==="delete"){if(await confirm("Delete Project?",`${block.title}\n\nThis removes only the project block from image-library.json. Underlying GitHub image files remain unless deleted separately.`,"Delete Project")){await safeDeleteBlock(blockId,block.title);await alertMsg("Project Deleted & Verified",`${block.title} was removed from image-library.json.\n\nUnderlying image files remain on GitHub.`);return}continue}
    await persistBeforeAction(blockId,r);
    if(r.action==="addImages")await addImagesMenu(blockId);else if(r.action==="shared")await importShared(blockId);else if(r.action==="createCategory")await createCategoryForProject(blockId);else if(r.action==="manageCategories")await manageCategories();else if(r.action==="previewImages"){let fresh=await liveLibrary();await previewGallery(fresh.json.blocks.find(b=>b.id===blockId))}else if(r.action.startsWith("image:")){let fresh=await liveLibrary(),b=fresh.json.blocks.find(x=>x.id===blockId);await imageAction(b,Number(r.action.split(":")[1]))}}
}
async function publishConvertedAdvanced(){let paths=await chooseConvertedPaths();if(!paths.length)return;let mode=await choose("Converted Destination",[{label:"Attach to Existing Project",id:"existing"},{label:"Create New Project",id:"new"}],"A similar title will never be used to guess the destination.");if(!mode)return;let block=mode.id==="existing"?await selectProject("Select the exact destination project by permanent Block ID."):await newProject();if(!block)return;let saved=await runBusy(()=>attachPathsToBlockId(block.id,paths));await alertMsg("Converted Images Attached & Verified",`${paths.length} image${paths.length===1?"":"s"} attached to ${saved.title}.\n\nBlock ID: ${saved.id}`);await openProject(saved)}
async function advancedTools(){while(true){let p=await choose("Advanced / Tools",[{label:"Health Check",id:"health"},{label:"Counts",id:"counts"},{label:"Export Live JSON",id:"export"},{label:"Reload Library",id:"reload"},{label:"Publish / Attach Converted Images",id:"converted"},{label:"Back",id:"back"}],"Maintenance tools are kept outside the normal project editing flow.");if(!p||p.id==="back")return;if(p.id==="health")await healthCheck();if(p.id==="counts")await counts();if(p.id==="export")await exportJson();if(p.id==="reload")await reloadLibrary();if(p.id==="converted")await publishConvertedAdvanced()}}
async function shareSheetStart(){if(!Array.isArray(args.images)||!args.images.length)return false;let block=await selectProject(`Select the destination before importing ${Math.min(args.images.length,MAX_BATCH)} shared photo${args.images.length===1?"":"s"}.`);if(!block)return true;await importShared(block.id);await openProject(block);return true}
async function main(){if(await shareSheetStart())return;while(true){let p=await choose("Spray GenX Image Manager v4.1",[{label:"Projects — Open / Edit / Upload",id:"projects"},{label:"＋ New Project",id:"new"},{label:"Advanced / Tools",id:"advanced"},{label:"Done",id:"done"}],"PRODUCTION · Project-first · Verified GitHub writes");if(!p||p.id==="done")break;if(p.id==="projects"){let b=await selectProject();if(b)await openProject(b)}if(p.id==="new"){let b=await newProject();if(b)await openProject(b)}if(p.id==="advanced")await advancedTools()}}

main().catch(async e=>await alertMsg("Image Manager Error",String(e.message||e)));
